const UNITS=[
{id:"u1",no:1,ko:"현재 vs 현재진행",en:"Simple vs -ing",pic:"now",
 big:"Simple present is the normal setting of your life. Present continuous is what's on the screen right now.",
 points:[
  {h:"Simple present = your profile",p:"Use it for habits, facts, and things that are generally true about you. It doesn't matter what you're doing at this second.",
   ex:["I [[work]] at a bank.","I [[drink]] coffee every morning.","My sister [[lives]] in Busan."]},
  {h:"-ing = happening now, or around now",p:"Use it for something in progress right now, or a temporary situation these days.",
   ex:["Sorry, I[['m driving]]. Can I call you back?","I[['m working]] from home this week.","I[['m reading]] a really good book these days."]},
  {h:"Same verb, different picture",p:"Simple feels permanent. -ing feels temporary.",
   ex:["I [[live]] in Seoul. (my home)","I[['m living]] with my sister for now. (not forever)","He's rude. → He[['s being]] rude today. (not his normal self)"]},
  {h:"-ing for plans you already set",p:"If the time and people are already decided, -ing works for the future. You'll need this a lot in OPIc role-plays.",
   ex:["I[['m meeting]] Jisoo tomorrow.","What [[are]] you [[doing]] this weekend?"]},
  {h:"State words usually stay simple",p:"know, like, want, need, believe, understand, own, belong, seem, mean are states, not actions. Nothing is 'in progress', so no -ing.",
   ex:["I [[know]] what you mean.","I [[think]] it's good. (my opinion) / I[['m thinking]] about quitting. (my mind is working on it)","I [[have]] a car. (own it) / I[['m having]] lunch. (eating = an action)"]},
  {h:"always + -ing = a complaint",p:"It means 'this happens too often, and it annoys me.'",
   ex:["He[['s always losing]] his keys!","You[['re always checking]] your phone."]}
 ],
 dialog:[["A","What [[do]] you [[do]]?"],["B","I [[work]] in marketing. But I[['m not working]] this week. I'm on vacation."],["A","Nice! So what [[are]] you [[doing]] these days?"],["B","I[['m taking]] a pottery class. I usually [[go]] on Tuesdays."],["A","[[Do]] you [[like]] it?"],["B","I [[love]] it. I[['m making]] a mug right now, actually. Well, I[['m trying]] to."]],
 mistakes:[
  ["I am go to school every day.","I go to school every day.","Habit → just 'I go'. Don't add 'am'."],
  ["What do you do now? — I watch TV.","What are you doing? — I'm watching TV.","'What do you do?' asks about your job. 'What are you doing?' asks about this moment."],
  ["I'm knowing him.","I know him.","know = a state. No -ing."],
  ["I'm usually going to the gym.","I usually go to the gym.","usually / always / every day = routine → simple."]
 ],
 opic:"'Tell me about your typical day' → simple present (I wake up at 7, I usually…). Then add 'These days, I'm…' to sound current and real."
},
{id:"u2",no:2,ko:"have p.p. 계속 용법",en:"From then until now",pic:"line",
 big:"have + p.p. connects the past to NOW. It started before, and it's still true today.",
 points:[
  {h:"Started in the past, still true now",p:"One line from a past point to now. The line is not finished.",
   ex:["I[['ve lived]] in Seoul for five years. (I still live there.)","I [[lived]] in Seoul for five years. (I don't live there now.)"]},
  {h:"for + length / since + starting point",p:"for two years, for a long time, for ages · since 2020, since high school, since I was a kid.",
   ex:["We[['ve been]] friends [[for]] ten years.","I[['ve had]] this phone [[since]] 2022.","She[['s worked]] here [[since]] she graduated."]},
  {h:"How long have you…?",p:"This is the natural way to ask about a time line up to now.",
   ex:["[[How long have you worked]] there?","[[How long have you known]] each other?","[[How long have you been]] married?"]},
  {h:"Great with state words",p:"know, have, be, like can't take -ing, so this is how you say how long.",
   ex:["I[['ve known]] her since middle school.","I[['ve always liked]] spicy food."]},
  {h:"Negative = a gap until now",p:"Nothing has happened from that point until now.",
   ex:["I [[haven't seen]] him for ages.","I [[haven't eaten]] since breakfast."]},
  {h:"Other jobs of have p.p. — same core",p:"Experience and fresh results also connect the past to now.",
   ex:["I[['ve been]] to Japan twice. (my experience up to now)","I[['ve lost]] my wallet. (it's still lost now)"]}
 ],
 dialog:[["A","[[How long have you lived]] in this neighborhood?"],["B","[[Since]] 2019. So about seven years."],["A","Then you must know all the good places."],["B","Ha, I[['ve known]] the owner of that noodle place for years."],["A","I [[haven't had]] good noodles since I moved here."],["B","Let's go, then. I [[haven't been]] there for a while either."]],
 mistakes:[
  ["I live here for 3 years.","I've lived here for 3 years.","'live' alone talks only about now. 'for 3 years' needs a line from the past."],
  ["I've lived here since 3 years.","I've lived here for 3 years.","Length → for. Starting point → since."],
  ["I know him since high school.","I've known him since high school.","since + now → have p.p."],
  ["I've lived in Busan when I was a kid.","I lived in Busan when I was a kid.","A finished time (when I was a kid, last year, in 2015) → simple past."]
 ],
 opic:"Background answers sound stronger with a time line: 'I've lived in my apartment for about four years.' 'I've worked at my company since 2021.'"
},
{id:"u3",no:3,ko:"have been ~ing",en:"Been doing",pic:"zigzag",
 big:"An activity started before and has been going on until now. The focus is on the doing, and on how long.",
 points:[
  {h:"Going on up to now",p:"The action started in the past and is probably still going.",
   ex:["I[['ve been studying]] English for six months.","It[['s been raining]] all day."]},
  {h:"Just stopped — you can see the result",p:"The activity just finished, and there's evidence now.",
   ex:["Sorry I'm sweaty. I[['ve been running]].","Your eyes are red. [[Have]] you [[been crying]]?"]},
  {h:"Doing vs done",p:"have been -ing = the activity (maybe not finished). have p.p. = the result or the number.",
   ex:["I[['ve been reading]] this book. (still reading)","I[['ve read]] this book. (finished)","I[['ve been writing]] emails all morning. / I[['ve written]] 20 emails."]},
  {h:"Lately / recently",p:"Perfect for talking about what's been going on in your life.",
   ex:["I[['ve been feeling]] tired lately.","What [[have]] you [[been up to]]? (= What have you been doing lately?)"]},
  {h:"Not with state words",p:"know, own, believe, belong don't take -ing.",
   ex:["I[['ve known]] him for years. (✗ been knowing)","But: I[['ve been having]] trouble sleeping. (having = experiencing, OK)"]},
  {h:"live / work: both OK",p:"I've lived here for 5 years ≈ I've been living here for 5 years. The -ing version feels a little more active or temporary.",
   ex:["I[['ve been working]] here since March."]}
 ],
 dialog:[["A","Hey! Long time no see. What [[have]] you [[been up to]]?"],["B","I[['ve been working]] a lot. And I[['ve been learning]] to swim."],["A","Swimming? How long [[have]] you [[been doing]] that?"],["B","About three months. I[['ve been going]] every morning before work."],["A","No wonder you look so healthy."],["B","Thanks! But I[['ve been sleeping]] badly. I'm so tired."]],
 mistakes:[
  ["I'm studying English for 2 years.","I've been studying English for 2 years.","for + up to now → have been -ing."],
  ["I've been knowing her for years.","I've known her for years.","know = a state."],
  ["I've been drinking three cups of coffee today.","I've had three cups of coffee today.","A number of finished things → have p.p."],
  ["I've been working here since 3 years.","I've been working here for 3 years.","Length → for."]
 ],
 opic:"'Recently, I've been getting into…' or 'I've been trying to…' is a great way to start answers about hobbies or changes in your life."
},
{id:"u4",no:4,ko:"수동태 be + p.p.",en:"The passive",pic:"spot",
 big:"Put the thing that receives the action in the spotlight. Who did it is unknown, not important, or obvious.",
 points:[
  {h:"Spotlight on the receiver",p:"Say what happened to it. The doer can stay hidden.",
   ex:["My bike [[was stolen]]. (I don't know who did it.)","This bridge [[was built]] in 1990."]},
  {h:"Everyday phrases you already need",p:"Many common phrases are really this pattern.",
   ex:["I [[was born]] in Daegu.","It's [[made]] in Korea.","The store [[is closed]].","Is this seat [[taken]]?"]},
  {h:"get + p.p. = the casual 'it happened' version",p:"In speech, get is very common, especially for sudden or unexpected changes.",
   ex:["My flight [[got canceled]].","We [[got lost]].","I [[got paid]] today!","He [[got fired]]."]},
  {h:"The time lives in 'be'",p:"Change be, keep the p.p.",
   ex:["My car [[is being fixed]], so I took the bus. (now)","The meeting [[has been moved]] to Friday.","It'll [[be done]] by tomorrow."]},
  {h:"by + doer, only when it matters",p:"Add 'by' only if the doer is new or interesting information.",
   ex:["This song [[was written by]] my favorite singer."]},
  {h:"Feelings and rules",p:"Lots of feelings and rules use be + p.p.",
   ex:["I'm [[interested]] in photography.","I'm [[worried]] about my exam.","I [[was told]] to wait here.","We're [[supposed to]] meet at seven."]}
 ],
 dialog:[["A","Why are you taking the bus? Where's your car?"],["B","It[['s being fixed]]. It [[got hit]] in the parking lot last week."],["A","Oh no! [[Was]] anyone [[hurt]]?"],["B","No, nobody was in it. But the back door [[was]] totally [[smashed]]."],["A","Will it [[be]] ready soon?"],["B","I [[was told]] it'll [[be done]] by Friday."]],
 mistakes:[
  ["I was borned in Seoul.","I was born in Seoul.","born is already the p.p."],
  ["It was happened yesterday.","It happened yesterday.","happen, arrive, die, sleep have no receiver, so no passive."],
  ["The package delivered yesterday.","The package was delivered yesterday.","The package didn't deliver anything. Someone delivered it."],
  ["I'm interesting in music.","I'm interested in music.","-ed = how you feel. -ing = what makes you feel it."]
 ],
 opic:"Use it for places and problems: 'My apartment was built about ten years ago.' 'The concert got canceled because of the rain.'"
},
{id:"u5",no:5,ko:"p.p.의 뜻",en:"What p.p. feels like",pic:"done",
 big:"A p.p. word carries one feeling: done. The action is finished, or someone or something received it.",
 points:[
  {h:"p.p. = done / received",p:"broken = someone broke it, so now it's in a broken state. closed, finished, used, lost work the same way.",
   ex:["My phone is [[broken]].","The shop is [[closed]].","I'm [[done]]!"]},
  {h:"p.p. before a noun = a description",p:"It describes the state of the thing.",
   ex:["a [[used]] car","[[frozen]] food","a [[locked]] door","I'm [[lost]]."]},
  {h:"-ed feeling vs -ing cause",p:"-ed = what you feel. -ing = what makes people feel it.",
   ex:["I'm [[bored]]. / This movie is [[boring]].","I'm [[confused]]. / The map is [[confusing]].","I was so [[embarrassed]]. / It was [[embarrassing]]."]},
  {h:"noun + p.p. = 'that was ~ed'",p:"Add a p.p. after a noun to say what was done to it.",
   ex:["a car [[made]] in Germany (= a car that was made in Germany)","the photos [[taken]] last night","a language [[spoken]] in many countries"]},
  {h:"One p.p., many frames",p:"The 'done' feeling stays the same. The frame around it changes.",
   ex:["I [[have finished]]. (done up to now)","It [[is finished]]. (it's in a finished state)","the work [[finished]] today (description)"]},
  {h:"get/have something done = someone does it for you",p:"You didn't do it yourself. Someone did it for you.",
   ex:["I [[got]] my hair [[cut]].","I [[had]] my phone [[fixed]]."]}
 ],
 dialog:[["A","Did you get a haircut?"],["B","Yeah, I [[got]] it [[cut]] yesterday. Do you like it?"],["A","Love it. You look so [[relaxed]]."],["B","I'm so [[relieved]]. My last haircut was a disaster. I was so [[embarrassed]]."],["A","Haha, that was a really [[embarrassing]] story."],["B","Don't remind me. Anyway, I'm [[done]] with that salon."]],
 mistakes:[
  ["I'm boring.","I'm bored.","'I'm boring' means you make other people bored!"],
  ["I cut my hair at a salon.","I got my hair cut at a salon.","Unless you cut it yourself."],
  ["a car making in Korea","a car made in Korea","The car received the action → p.p."],
  ["I'm so exciting about the trip.","I'm so excited about the trip.","You feel it → -ed."]
 ],
 opic:"Feeling words make your stories vivid: 'I was so surprised.' 'It was a little disappointing.' 'I felt really relieved.'"
},
{id:"u6",no:6,ko:"would 다시 보기",en:"The feeling of would",pic:"would",
 big:"would = will, but one step away: away from reality (imagining), away in time (the past), or a polite step back.",
 points:[
  {h:"Imagining (not real now)",p:"Use it for situations that aren't true right now. After 'if', use the past form.",
   ex:["I[['d travel]] more if I [[had]] more time.","If I were you, I[['d take]] the job.","I [[would never]] do that."]},
  {h:"Polite and soft",p:"would sounds gentler than will or want.",
   ex:["[[Would]] you like some coffee?","I[['d like]] a latte, please.","[[Would]] you mind closing the window?","That [[would be]] great."]},
  {h:"I'd love to / I'd rather",p:"I'd love to = yes, happily. I'd rather = I prefer to.",
   ex:["I[['d love to]] come!","I[['d rather]] stay home tonight."]},
  {h:"Past habits (repeated actions)",p:"For things you did again and again in the past. For past states (be, have, live, like), use 'used to'.",
   ex:["When I was a kid, I [[would]] play outside until dark.","I [[used to]] have long hair. (✗ I would have long hair)"]},
  {h:"will, seen from the past",p:"When you report what someone said or thought before.",
   ex:["He said he[['d call]] me. (He said, 'I'll call you.')","I knew you[['d like]] it."]},
  {h:"would have p.p. = imagining the past",p:"It didn't happen. You're imagining another past.",
   ex:["I [[would have come]] if you'd told me. (I didn't come.)","That [[would have been]] fun."]},
  {h:"wouldn't = refused",p:"Something or someone refused to work or act.",
   ex:["My car [[wouldn't]] start this morning.","The kid [[wouldn't]] stop crying."]}
 ],
 dialog:[["A","[[Would]] you like to grab dinner on Friday?"],["B","I[['d love to]]! Where [[would]] you want to go?"],["A","How about that Thai place? I think you[['d like]] it."],["B","Perfect. When I lived in Bangkok, I [[would]] eat pad thai every day."],["A","Then this [[would be]] a good test, haha."],["B","Honestly, if I had time, I[['d move]] back there."]],
 mistakes:[
  ["If I have money, I would buy a house.","If I had money, I would buy a house.","Imagining → past form after if (had), would in the other part."],
  ["I would like go.","I'd like to go.","would like + to + verb."],
  ["When I was young, I would be shy.","I used to be shy.","A past state → used to."],
  ["If I would know, I would tell you.","If I knew, I would tell you.","No would after if (in imagining)."]
 ],
 opic:"Role-play questions: 'Would it be possible to…?', 'Would you mind…?'. Imagining questions: 'If you could…, what would you do?' → 'I would…'."
},
{id:"u7",no:7,ko:"문장의 절 구조",en:"Building with clauses",pic:"blocks",
 big:"A clause is one 'someone + does/is something' unit. A long sentence is just small clauses connected. Say one, then add the next.",
 points:[
  {h:"One clause = subject + verb",p:"Count the subject-verb pairs.",
   ex:["[[I was]] tired. (1)","[[I was]] tired, so [[I went]] home early. (2)"]},
  {h:"Add a reason, a time, or a condition",p:"because, when, if, before, after, while, although, until, as soon as. Talking about the future after when/if? Use the present.",
   ex:["I stayed home [[because it was raining]].","[[When I get home]], I usually take a shower.","[[If it's sunny tomorrow]], let's go hiking. (✗ If it will be)"]},
  {h:"A clause can be a 'thing'",p:"that / what / if + clause works like one big noun.",
   ex:["I think [[(that) he's right]].","I don't know [[what he wants]].","I'm not sure [[if it's open]].","[[What I need]] is a break."]},
  {h:"Question inside a sentence = normal order",p:"Once a question goes inside a sentence, it becomes subject + verb again.",
   ex:["Where is the station? → Do you know [[where the station is]]?","What time does it start? → Can you tell me [[what time it starts]]?"]},
  {h:"A clause can describe a noun",p:"This is the relative clause (see unit 8).",
   ex:["the guy [[who lives next door]]","the place [[where we met]]"]},
  {h:"How natives build long answers",p:"Main idea first. Then add: because…, so…, which…, but…, and then…",
   ex:["I love my neighborhood [[because it's quiet]], [[which is rare in Seoul]]."]}
 ],
 dialog:[["A","Do you know [[what time the store closes]]?"],["B","I'm not sure, but I think [[it closes at nine]]."],["A","[[If it's still open when we get there]], let's buy some snacks."],["B","Okay. [[Although I already ate]], I could eat again."],["A","Ha. [[What I really want]] is ice cream."],["B","Same. I'll text my sister to ask [[if she wants some]]."]],
 mistakes:[
  ["Do you know where is the bathroom?","Do you know where the bathroom is?","Inside a sentence → normal order."],
  ["When I will finish work, I'll call you.","When I finish work, I'll call you.","Future after when / if → present."],
  ["Although it was raining, but we went out.","Although it was raining, we went out.","Use one connector, not two."],
  ["I don't know what does he want.","I don't know what he wants.","No 'does' inside the sentence."]
 ],
 opic:"OPIc raters listen for connected speech (paragraphs = IH/AL). Practice: one clause → add because → add so → add which."
},
{id:"u8",no:8,ko:"관계사",en:"Name tags for nouns",pic:"tag",
 big:"A relative clause is a name tag on a noun. It tells you WHICH one, or adds extra information about it.",
 points:[
  {h:"who / that → people",p:"The clause tells you which person.",
   ex:["I have a friend [[who lives in Canada]].","The woman [[that helped me]] was so kind."]},
  {h:"which / that → things",p:"The clause tells you which thing.",
   ex:["The phone [[that I bought last week]] is already broken.","It's a song [[that always makes me cry]]."]},
  {h:"Drop it when a new subject follows",p:"If the next word is a new subject (I, you, he…), you can drop who/that. Natives usually do.",
   ex:["the movie [[(that) I watched]] yesterday","the person [[(who) I talked to]]","Everything [[I said]] was true."]},
  {h:"where / when → places and times",p:"For places use where. For times, natives often just drop when.",
   ex:["the café [[where we first met]]","the day [[(when) I got my license]]"]},
  {h:"whose = his / her / their",p:"Shows that something belongs to that person.",
   ex:["I have a friend [[whose dad is a pilot]]."]},
  {h:"what = the thing(s) that",p:"what already contains the noun. Don't say 'the thing what'.",
   ex:["[[What I want]] is some sleep.","That's not [[what I meant]].","Do [[what you love]]."]},
  {h:", which… = your comment on the whole sentence",p:"Super common in speech for adding your reaction at the end.",
   ex:["He didn't show up, [[which was really annoying]].","We got a free upgrade, [[which was nice]]."]},
  {h:"Preposition at the end (casual)",p:"In speech, the little word goes to the end.",
   ex:["the person [[I live with]]","the city [[I grew up in]]","something [[I'm interested in]]"]}
 ],
 dialog:[["A","Who's the guy [[you were talking to]]?"],["B","That's Minho. He's the friend [[I told you about]], the one [[who works at the airport]]."],["A","The one [[whose sister is a singer]]?"],["B","Yes! And the café [[where we were sitting]] is his. He just opened it, [[which is amazing]]."],["A","Is that [[what he always wanted to do]]?"],["B","Exactly. It's something [[he's been dreaming about]] for years."]],
 mistakes:[
  ["I have a friend who she lives in Canada.","I have a friend who lives in Canada.","'who' already takes the place of 'she'."],
  ["the thing what I want","the thing (that) I want / what I want","'what' already includes 'the thing'."],
  ["the city where I grew up in","the city where I grew up / the city I grew up in","where already includes 'in'."],
  ["He was late, that was annoying.","He was late, which was annoying.","Commenting on a whole sentence → , which"]
 ],
 opic:"Describing places and people: 'It's a small café that has big windows, which makes it really bright.'"
}
];

